preConditionHook:
// Swing low rejection (Brian's notes P13-b, TRIAGE P13, p. 36). The bar's low
// comes within tol ATR of the most recent CONFIRMED swing low, on EITHER side,
// and the bar REJECTS it: it closes above the swing low with a lower wick
// (min(open, close) - low) of at least w of its range. LONG. Short mirrors at
// the latest swing high. The note's context -- "the next swing low is higher"
// (P13-a) -- is HigherSwingLow and is placed separately, never folded in here.
//
// Not SwingPointTestHolds (one-sided: may not trade below the level) and not
// FailedSwingBreakoutReversal (must trade below, depth unbounded, no wick test):
// this is a two-sided band with a bounded undercut AND a wick test, so no single
// placement of either reproduces it.
//
// Pivot scan inlined from SwingHigh at Occurrence 1 (the twin calls SwingLow /
// SwingHigh, VERIFIED): MEASURED mixed test -- at-or-beyond the strength OLDER
// bars, STRICTLY beyond the strength NEWER bars (the smaller pk) -- lag exactly
// strength, offsets strength..maxBarsBack-1, deepest bar maxBarsBack - 1 +
// strength, el_* for the relational tolerance; existence is a bool, never a
// price test against -1. MinList/MaxList pick between open and close, tick-grid
// operands inside their ACCEPTED scope, so plain comparisons stand in.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingPointTestHolds's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;), because EL
// evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
lo1 = 0.0;
haveLo1 = false;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_lt(low[pj], low[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_le(low[pj], low[pk])) { pok = false; break; }
        }
    }
    if (pok) { lo1 = low[pj]; haveLo1 = true; break; }
}
hi1 = 0.0;
haveHi1 = false;
for (pj = (int)strength; pj <= (int)maxBarsBack - 1; ++pj) {
    pok = true;
    for (pk = pj - (int)strength; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) { pok = false; break; }
    }
    if (pok) {
        for (pk = pj + 1; pk <= pj + (int)strength; ++pk) {
            if (!el_ge(high[pj], high[pk])) { pok = false; break; }
        }
    }
    if (pok) { hi1 = high[pj]; haveHi1 = true; break; }
}
bodyBot = open[0];
if (close[0] < bodyBot) bodyBot = close[0];
bodyTop = open[0];
if (close[0] > bodyTop) bodyTop = close[0];
